728:     function renderBarChart(containerId, obj, labelMap = {}) {
729:       const el = document.getElementById(containerId);
730:       const entries = Object.entries(obj || {}).sort((a, b) => b[1] - a[1]);
731:       if (!entries.length) {
732:         el.innerHTML = `<p style="color:var(--muted); font-size:0.85rem;">0 records collected in this dimension yet.</p>`;
