734:       }
735:       const maxVal = Math.max(...entries.map(e => e[1]), 1);
736:       el.innerHTML = entries.map(([k, v]) => {
737:         const pct = Math.round((v / maxVal) * 100);
738:         const lbl = labelMap[k] || k;
739:         return `
740:           <div class="bar-row">
741:             <span class="bar-label" title="${lbl}">${lbl}</span>
742:             <div class="bar-track"><div class="bar-fill" style="width:${pct}%"></div></div>
743:             <span class="bar-val">${v}</span>
744:           </div>`;
745:       }).join("");
746:     }
